import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from radialStackedBar ----
type TrafficHour = {
  hour: string;
  browse: number;
  search: number;
  checkout: number;
  api: number;
};

const TRAFFIC_SERIES = ['browse', 'search', 'checkout', 'api'] as const;

/** Synthetic one-day request profile, thousands of requests per hour. Cyclical by design, which is what a radial layout is for. */
const hourlyTraffic: TrafficHour[] = [
  { hour: '00', browse: 42, search: 18, checkout: 9, api: 55 },
  { hour: '01', browse: 31, search: 13, checkout: 6, api: 48 },
  { hour: '02', browse: 24, search: 10, checkout: 4, api: 44 },
  { hour: '03', browse: 20, search: 8, checkout: 3, api: 42 },
  { hour: '04', browse: 22, search: 9, checkout: 4, api: 45 },
  { hour: '05', browse: 30, search: 12, checkout: 6, api: 52 },
  { hour: '06', browse: 48, search: 20, checkout: 10, api: 66 },
  { hour: '07', browse: 76, search: 33, checkout: 17, api: 88 },
  { hour: '08', browse: 108, search: 48, checkout: 25, api: 112 },
  { hour: '09', browse: 134, search: 61, checkout: 33, api: 131 },
  { hour: '10', browse: 148, search: 69, checkout: 38, api: 142 },
  { hour: '11', browse: 152, search: 71, checkout: 41, api: 146 },
  { hour: '12', browse: 141, search: 66, checkout: 39, api: 140 },
  { hour: '13', browse: 138, search: 64, checkout: 37, api: 138 },
  { hour: '14', browse: 146, search: 70, checkout: 40, api: 144 },
  { hour: '15', browse: 151, search: 73, checkout: 43, api: 149 },
  { hour: '16', browse: 147, search: 70, checkout: 41, api: 145 },
  { hour: '17', browse: 133, search: 62, checkout: 36, api: 136 },
  { hour: '18', browse: 118, search: 55, checkout: 32, api: 124 },
  { hour: '19', browse: 126, search: 60, checkout: 35, api: 129 },
  { hour: '20', browse: 139, search: 67, checkout: 40, api: 138 },
  { hour: '21', browse: 130, search: 62, checkout: 37, api: 131 },
  { hour: '22', browse: 101, search: 47, checkout: 27, api: 110 },
  { hour: '23', browse: 68, search: 30, checkout: 17, api: 80 }
];

/** One row per angular band: its label plus a value for each stacked series. */
type Row = { hour: string; browse: number; search: number; checkout: number; api: number };

/** The rows, plus the series to stack in order from the inner ring outward. */
export type Data = { rows: Row[]; series: Exclude<keyof Row, 'hour'>[] };

const DEMO: Data = { rows: hourlyTraffic, series: [...TRAFFIC_SERIES] };

const MAX_SIZE = 520;
const MARGIN = 24;
const INNER_RADIUS_RATIO = 0.38;
const LEGEND_ROW_HEIGHT = 18;

const formatCount = d3.format(',');
const formatTick = d3.format('~s');

export default function RadialStackedBarChart({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.min(width, MAX_SIZE);
  const outerRadius = Math.min(width, height) / 2 - MARGIN;
  const innerRadius = outerRadius * INNER_RADIUS_RATIO;

  const series: d3.Series<Row, string>[] = useMemo(
    () => d3.stack<Row, string>().keys(data.series)(data.rows),
    [data]
  );

  const x = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(data.rows.map((d) => d.hour))
        .range([0, 2 * Math.PI])
        .align(0),
    [data]
  );

  const y = useMemo(
    () =>
      d3
        .scaleRadial()
        .domain([0, d3.max(series, (s) => d3.max(s, (d) => d[1]) ?? 0) ?? 0])
        .range([innerRadius, outerRadius]),
    [series, innerRadius, outerRadius]
  );

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.series)
        .range(d3.schemeObservable10),
    [data]
  );

  // A radial y-scale keeps the bar segments area-proportional rather than radius-proportional.
  const arc = useMemo(
    () =>
      d3
        .arc<d3.SeriesPoint<Row>>()
        .innerRadius((d) => y(d[0]))
        .outerRadius((d) => y(d[1]))
        .startAngle((d) => x(d.data.hour) ?? 0)
        .endAngle((d) => (x(d.data.hour) ?? 0) + x.bandwidth())
        .padAngle(1.5 / innerRadius)
        .padRadius(innerRadius),
    [x, y, innerRadius]
  );

  const rings = useMemo(() => y.ticks(5).slice(1), [y]);

  if (width === 0) return null;

  const midAngle = (hour: string) => (x(hour) ?? 0) + x.bandwidth() / 2;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Radial stacked bar chart of hourly request volume by request type"
    >
      {series.map((s) => (
        <g key={s.key} fill={color(s.key)}>
          {s.map((d) => (
            <path key={d.data.hour} d={arc(d) ?? undefined}>
              <title>{`${d.data.hour}:00 ${s.key}\n${formatCount(d[1] - d[0])}k`}</title>
            </path>
          ))}
        </g>
      ))}

      <g textAnchor="middle" fontSize={10} fill="var(--muted)">
        {data.rows.map((d) => {
          const angle = midAngle(d.hour);
          // Labels on the left half read upside down unless their local frame is flipped.
          const isLeftHalf = (angle + Math.PI / 2) % (2 * Math.PI) < Math.PI;
          return (
            <g
              key={d.hour}
              transform={`rotate(${(angle * 180) / Math.PI - 90}) translate(${innerRadius},0)`}
            >
              <line x2={-5} stroke="var(--line)" />
              <text
                transform={isLeftHalf ? 'rotate(90) translate(0,16)' : 'rotate(-90) translate(0,-9)'}
              >
                {d.hour}
              </text>
            </g>
          );
        })}
      </g>

      <g fill="none" textAnchor="middle" fontSize={10}>
        {rings.map((tick) => (
          <g key={tick}>
            <circle r={y(tick)} stroke="var(--line)" strokeOpacity={0.8} />
            <text
              y={-y(tick)}
              dy="0.35em"
              fill="var(--muted)"
              stroke="var(--bg)"
              strokeWidth={4}
              paintOrder="stroke"
            >
              {formatTick(tick)}
            </text>
          </g>
        ))}
      </g>

      <g fontSize={11}>
        {data.series.map((key, i) => (
          <g
            key={key}
            transform={`translate(${-innerRadius * 0.55},${
              (i - data.series.length / 2) * LEGEND_ROW_HEIGHT
            })`}
          >
            <rect width={11} height={11} fill={color(key)} />
            <text x={17} y={5.5} dy="0.35em" fill="var(--text)">
              {key}
            </text>
          </g>
        ))}
      </g>
    </svg>
  );
}
